package com.inventra.backend.model;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.index.CompoundIndex; import org.springframework.data.mongodb.core.mapping.Document; import java.time.LocalDateTime;
@Document(collection="inventories") @CompoundIndex(name="warehouse_product_unique",def="{'warehouseId':1,'productId':1}",unique=true) public class Inventory { @Id private String id; private String warehouseId; private String productId; private int quantity; private int reservedQuantity; private LocalDateTime updatedAt=LocalDateTime.now(); public Inventory(){} public String getId(){return id;} public void setId(String v){id=v;} public String getWarehouseId(){return warehouseId;} public void setWarehouseId(String v){warehouseId=v;} public String getProductId(){return productId;} public void setProductId(String v){productId=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public int getReservedQuantity(){return reservedQuantity;} public void setReservedQuantity(int v){reservedQuantity=v;} public int getAvailableQuantity(){return Math.max(0,quantity-reservedQuantity);} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
